pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 blockOffset) public {
        // Ensure block.number is at least 1, and blockOffset > 0 so settle can proceed
        vm.assume(blockOffset > 0);
        vm.assume(blockOffset < 1000); // avoid extremely large values

        // Provide 1 ether for lockInGuess
        vm.deal(address(this), 1 ether);

        // Call lockInGuess
        c.lockInGuess(guessHash);

        // Mine enough blocks so block.number > lock block
        vm.roll(block.number + blockOffset);

        // Call settle and capture the result (revert or success)
        // The reference C never transfers ether because guess will never match the blockhash
        // (since blockhash(block.number) is unknown during fuzzing; hash collision probability negligible)
        // So after settle, the contract should still hold the original 1 ether
        uint256 contractBalanceBefore = address(c).balance;

        // Try settle - it may revert if block.number not > lock block, but we ensured it is
        c.settle();

        uint256 contractBalanceAfter = address(c).balance;

        // General rule: The contract balance should not decrease, i.e., no transfer should occur
        // This holds for reference C because guess != answer (no match), and fails for mutant M (transfer when guess != answer)
        assertTrue(contractBalanceAfter >= contractBalanceBefore, "Balance decreased - unexpected transfer");
    }
}

