import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash, address player) public {
        vm.assume(player != address(0) && player != address(this));
        vm.deal(player, 3 ether);

        // First lock in
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);

        // First settle - in reference, this will succeed or revert based on guess correctness
        (bool success1, ) = address(c).call{value: 0 ether}(abi.encodeWithSignature("settle()"));

        // In reference, after settle, the guess is reset so we can lock in again
        // In mutant, after settle, guess is NOT reset, so a second settle would use the same block

        // Second lock in attempt - reference allows it because guess was reset
        bool canLockInAgain;
        if (success1) {
            (canLockInAgain, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));
        }

        // The property: in reference, if first settle succeeded, second lockIn must succeed
        // In mutant, the first settle succeeds but the guess is not reset, so second lockIn reverts
        assertTrue(!success1 || canLockInAgain);
    }
}

