pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess1, bytes32 guess2) public {
        vm.assume(guess1 != guess2);
        vm.deal(address(this), 2 ether);

        // First lockInGuess
        c.lockInGuess{value: 1 ether}(guess1);

        // First settle with wrong guess should revert because transfer fails (balance 0 after first lock)
        vm.deal(address(this), 3 ether);
        c.lockInGuess{value: 1 ether}(guess2); // this will revert because block not reset by mutate

        // Actually the bug is that after settle, the original contract resets block so lockInGuess works again
        // The mutant does not reset, so second lockInGuess reverts
        // We need to observe that after a first lockInGuess, calling settle (which will revert due to wrong guess) 
        // then trying lockInGuess again should succeed in reference but fail in mutant

        bool success;
        // Call settle - it will revert because wrong guess (transfer fails? Actually it just doesn't transfer)
        // But in reference, block gets reset anyway; in mutant, block stays
        (success, ) = address(c).call(abi.encodeWithSignature("settle()"));
        // Now try lockInGuess again
        bytes memory data = abi.encodeWithSignature("lockInGuess(bytes32)", guess1);
        (bool ok, ) = address(c).call{value: 1 ether}(data);
        // In reference, ok should be true; in mutant, false
        assertTrue(ok || !success); // general rule: if settle reverted, then lockInGuess should succeed (reference) OR if settle succeeded, then lockInGuess may fail
    }
}
